BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "cpu_products" (
	"product_name"	TEXT,
	"product_sku"	TEXT,
	"prime_price"	REAL,
	"mdcomp_price"	REAL,
	"vedant_price"	REAL,
	"pcstudio_price"	REAL,
	"clarion_price"	REAL,
	"ehubs_price"	REAL,
	"prime_stock"	VARCHAR,
	"mdcomp_stock"	VARCHAR,
	"vedant_stock"	VARCHAR,
	"pcstudio_stock"	VARCHAR,
	"clarion_stock"	VARCHAR,
	"ehubs_stock"	VARCHAR,
	PRIMARY KEY("product_sku")
);
CREATE TABLE IF NOT EXISTS "cpu_product_links" (
	"product_sku"	TEXT,
	"prime_link"	TEXT,
	"mdcomp_link"	TEXT,
	"vedant_link"	TEXT,
	"pcstudio_link"	TEXT,
	"clarion_link"	TEXT,
	"ehubs_link"	TEXT,
	PRIMARY KEY("product_sku"),
	FOREIGN KEY("product_sku") REFERENCES "cpu_products"("product_sku")
);
CREATE TABLE IF NOT EXISTS "ssd_products" (
	"product_name"	TEXT,
	"product_sku"	TEXT,
	"prime_price"	REAL,
	"mdcomp_price"	REAL,
	"vedant_price"	REAL,
	"pcstudio_price"	REAL,
	"clarion_price"	REAL,
	"ehubs_price"	REAL,
	"prime_stock"	VARCHAR,
	"mdcomp_stock"	VARCHAR,
	"vedant_stock"	VARCHAR,
	"pcstudio_stock"	VARCHAR,
	"clarion_stock"	VARCHAR,
	"ehubs_stock"	VARCHAR,
	PRIMARY KEY("product_sku")
);
CREATE TABLE IF NOT EXISTS "ssd_product_links" (
	"product_sku"	TEXT,
	"prime_link"	TEXT,
	"mdcomp_link"	TEXT,
	"vedant_link"	TEXT,
	"pcstudio_link"	TEXT,
	"clarion_link"	TEXT,
	"ehubs_link"	TEXT,
	"date_added"	DATE,
	PRIMARY KEY("product_sku"),
	FOREIGN KEY("product_sku") REFERENCES "ssd_products"("product_sku")
);
CREATE TABLE IF NOT EXISTS "ram_products" (
	"product_name"	TEXT,
	"product_sku"	TEXT,
	"prime_price"	REAL,
	"mdcomp_price"	REAL,
	"vedant_price"	REAL,
	"pcstudio_price"	REAL,
	"clarion_price"	REAL,
	"ehubs_price"	REAL,
	"prime_stock"	VARCHAR,
	"mdcomp_stock"	VARCHAR,
	"vedant_stock"	VARCHAR,
	"pcstudio_stock"	VARCHAR,
	"clarion_stock"	VARCHAR,
	"ehubs_stock"	VARCHAR,
	PRIMARY KEY("product_sku")
);
CREATE TABLE IF NOT EXISTS "ram_product_links" (
	"product_sku"	TEXT,
	"prime_link"	TEXT,
	"mdcomp_link"	TEXT,
	"vedant_link"	TEXT,
	"pcstudio_link"	TEXT,
	"clarion_link"	TEXT,
	"ehubs_link"	TEXT,
	PRIMARY KEY("product_sku"),
	FOREIGN KEY("product_sku") REFERENCES "ram_products"("product_sku")
);
CREATE TABLE IF NOT EXISTS "historical_prices" (
	"id"	INTEGER,
	"sku"	TEXT NOT NULL,
	"category"	TEXT NOT NULL,
	"date"	TEXT NOT NULL,
